(function(){
  // =========================
  // Config
  // =========================
  const TARGET_COUNTRY = 'PR';
  const PARENT_IDS = new Set(['8','170','198']);              // ES, PT, EN (IDs distintos)
  const HIDE_CHILDREN = new Set(['10','11','199','202','177','180']);

  // =========================
  // Detecta país atual
  // =========================
  function readGeoCountry(){
    try {
      if (typeof window.currentGeoCountryCode === 'function') {
        const c = window.currentGeoCountryCode();
        if (c) return c.toUpperCase();
      }
    } catch(e){}
    // Fallback: select (há 2 no header; usamos por "name")
    const selects = document.querySelectorAll('select[name="geot_dropdown"]');
    for (const sel of selects) {
      const v = (sel.value || '').trim();
      if (v) return v.toUpperCase();
      const opt = sel.options?.[sel.selectedIndex];
      if (opt?.value) return String(opt.value).toUpperCase();
    }
    // Fallback: selectize visível
    const it = document.querySelector('.selectize-control.geot_dropdown .selectize-input .item, .selectize-control.geot-ddslick .selectize-input .item');
    if (it) {
      const v = (it.getAttribute('data-value') || it.textContent || '').trim();
      if (v) return v.toUpperCase();
    }
    return '';
  }

  // =========================
  // Filtro PR → oculta children
  // =========================
  function applyPRFilter(){
    const country = readGeoCountry();
    if (country !== TARGET_COUNTRY) return;

    const menu = document.getElementById('geo-menu');
    if (!menu) return;

    // 1) Oculta botões de child na coluna do meio
    PARENT_IDS.forEach(pid => {
      // Oculta os <button class="child-btn" ...>
      const childBtns = menu.querySelectorAll(`.geo-column-children .child-btn[data-parent="${pid}"]`);
      childBtns.forEach(btn => {
        const cid = String(btn.getAttribute('data-child') || '').trim();
        const li  = btn.closest('li');
        if (HIDE_CHILDREN.has(cid) && li) {
          li.style.display = 'none';
          li.classList.add('geo-hidden-by-rule');
        }
      });

      // 2) Oculta os grupos de soluções correspondentes na coluna da direita
      const groups = menu.querySelectorAll(`.geo-column-solutions .solutions-group[data-parent="${pid}"]`);
      groups.forEach(g => {
        const cid = String(g.getAttribute('data-child') || '').trim();
        if (HIDE_CHILDREN.has(cid)) {
          g.classList.remove('active');
          g.classList.add('geo-hidden-by-rule');
          g.style.display = 'none';
        }
      });

      // 3) Se o "active" atual foi ocultado, escolher um restante
      const stillActive = menu.querySelector(`.geo-column-children .child-btn[data-parent="${pid}"].active`);
      if (stillActive && stillActive.closest('li')?.classList.contains('geo-hidden-by-rule')) {
        stillActive.classList.remove('active');
      }
      const visibleBtns = Array.from(menu.querySelectorAll(`.geo-column-children .child-btn[data-parent="${pid}"]`))
        .filter(b => b.closest('li') && b.closest('li').style.display !== 'none');

      if (visibleBtns.length === 1) {
        // Ativa a ÚNICA subcategoria disponível
        const onlyBtn = visibleBtns[0];
        if (!onlyBtn.classList.contains('active')) {
          onlyBtn.classList.add('active');
          // aciona a troca de grupo como se fosse clique
          onlyBtn.dispatchEvent(new Event('click', {bubbles:true}));
        } else {
          // garante que o grupo correspondente esteja ativo/visível
          const cid = String(onlyBtn.getAttribute('data-child') || '').trim();
          const grp = menu.querySelector(`.geo-column-solutions .solutions-group[data-parent="${pid}"][data-child="${cid}"]`);
          if (grp) {
            menu.querySelectorAll(`.geo-column-solutions .solutions-group[data-parent="${pid}"]`).forEach(g => g.classList.remove('active'));
            grp.classList.add('active');
            grp.style.display = '';
          }
        }
      }
    });
  }

  // =========================
  // Hooks para reexecutar
  // =========================

  // roda já
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', applyPRFilter, {once:true});
  } else {
    applyPRFilter();
  }
  window.addEventListener('load', applyPRFilter);

  // ao trocar o país no select geotargeting
  document.addEventListener('change', function(e){
    const t = e.target;
    if (t && t.matches && t.matches('select[name="geot_dropdown"]')) {
      // pequeno delay porque selectize atualiza async
      setTimeout(applyPRFilter, 0);
    }
  }, true);

  // clicks que repovoam/alteram o menu
  ['click','touchend','pointerup'].forEach(evt => {
    document.addEventListener(evt, function(e){
      if (e.target.closest('.parent-btn') || e.target.closest('.child-btn') ||
          e.target.closest('#geo-menu-open') || e.target.closest('#mobile-solutions-btn')) {
        setTimeout(applyPRFilter, 0);
      }
    }, {passive:true});
  });

  // MutationObserver no modal/DOM do menu (repovoamentos via jQuery)
  const modal = document.getElementById('geo-menu-modal') || document.body;
  if (modal) {
    new MutationObserver(() => { setTimeout(applyPRFilter, 0); })
      .observe(modal, {subtree:true, childList:true, attributes:true, attributeFilter:['class','style']});
  }

  // se existir queueClean() no seu stack, reusa-o para manter ordem
  try {
    if (typeof queueClean === 'function') {
      const _qc = queueClean;
      window.queueClean = function(){
        _qc();
        // roda no fim da limpeza
        setTimeout(applyPRFilter, 0);
      };
    }
  } catch(e){}
})();


(function(){
  // Reusa a mesma detecção de país
  function readGeoCountry(){
    try {
      if (typeof window.currentGeoCountryCode === 'function') {
        const c = window.currentGeoCountryCode();
        if (c) return c.toUpperCase();
      }
    } catch(e){}
    const selects = document.querySelectorAll('select[name="geot_dropdown"]');
    for (const sel of selects){
      const v = (sel.value || '').trim();
      if (v) return v.toUpperCase();
      const opt = sel.options?.[sel.selectedIndex];
      if (opt?.value) return String(opt.value).toUpperCase();
    }
    const it = document.querySelector('.selectize-control.geot_dropdown .selectize-input .item, .selectize-control.geot-ddslick .selectize-input .item');
    if (it){
      const v = (it.getAttribute('data-value') || it.textContent || '').trim();
      if (v) return v.toUpperCase();
    }
    return '';
  }

  // Helpers
  function normalizeLabel(s){
    return (s||'').toString()
      .normalize('NFD').replace(/\p{Diacritic}/gu,'')
      .toLowerCase()
      .replace(/\s+/g,' ')
      .trim();
  }
  function normalizePath(url){
    try{
      const u = new URL(url, location.origin);
      const segs = u.pathname.split('/').filter(Boolean);
      return segs.length ? normalizeLabel(segs[segs.length-1]) : '';
    }catch(e){ return ''; }
  }
  function parseQueriedParentIds(root){
    const ids = new Set();
    (root || document).querySelectorAll('.jet-listing-grid__items[data-queried-id]').forEach(n=>{
      const v = n.getAttribute('data-queried-id') || '';
      const m = v.match(/\d+/g);
      if (m) m.forEach(id => ids.add(id));
    });
    return ids;
  }

  // -------- Config (mesma política do cabeçalho) --------
  const TARGET_COUNTRY = 'PR';
  const PARENT_IDS     = new Set(['8','170','198']); // parents válidos (um por idioma)
  // IDs de children conhecidos (quando coincidem)
  const HIDE_IDS       = new Set(['10','11','199','202','177','180']);
  // Nomes bloqueados (PT/ES/EN)
  const HIDE_NAMES     = new Set([
    // cooperativas
    'cooperativas',
    // pequenas/médias
    'instituciones pequenas a medianas',
    'instituciones pequeñas a medianas',
    'pequenas e medias empresas',
    'pequenas e medias',
    'small to medium institutions',
    'small and medium institutions'
  ]);
  // Slugs comuns nas URLs
  const HIDE_SLUGS     = new Set([
    'cooperativas',
    'cooperativas-pt-br',
    'pequenas-a-medianas',
    'pequenas-e-medias-empresas',
    'small-to-medium-institutions',
    'small-and-medium-institutions'
  ]);

  // Decide se deve ocultar pelo trio (id/nome/slug)
  function shouldHide({postId, titleKey, slugKey}){
    if (postId && HIDE_IDS.has(String(postId))) return true;
    if (titleKey && HIDE_NAMES.has(titleKey))   return true;
    if (slugKey && HIDE_SLUGS.has(slugKey))     return true;
    return false;
  }

  // ---------- Subcategory list ----------
  function filterSubcategoryList(){
    if (readGeoCountry() !== TARGET_COUNTRY) return;

    document.querySelectorAll('.subcategory-list').forEach(section=>{
      // Confere se pertence a um parent alvo
      const parents = parseQueriedParentIds(section);
      const intersects = Array.from(parents).some(id => PARENT_IDS.has(String(id)));
      if (!intersects) return;

      section.querySelectorAll('.jet-listing-grid__items').forEach(grid=>{
        grid.querySelectorAll('.jet-listing-grid__item').forEach(item=>{
          const postId  = item.getAttribute('data-post-id') || '';
          const titleEl = item.querySelector('.elementor-heading-title');
          const titleKey= normalizeLabel(titleEl?.textContent || '');
          const linkWrap= item.querySelector('.jet-engine-listing-overlay-wrap');
          const a       = item.querySelector('a');
          const href    = linkWrap?.getAttribute('data-url') || a?.href || '';
          const slugKey = normalizePath(href);
          if (shouldHide({postId, titleKey, slugKey})) {
            item.remove(); // remove do DOM
          }
        });
      });
    });
  }

  // ---------- Filter select ----------
  function filterSolutionSelect(){
    if (readGeoCountry() !== TARGET_COUNTRY) return;

    document.querySelectorAll('.solution_filter_add').forEach(section=>{
      // tenta vincular a um grid irmão para ler o parent
      const nearGrid = section.closest('.elementor-element')?.parentElement?.querySelector('.jet-listing-grid__items[data-queried-id]')
                      || document.querySelector('#subcategories .jet-listing-grid__items[data-queried-id]');
      let intersects = true; // se não achar grid, ainda assim aplica
      if (nearGrid){
        const parents = parseQueriedParentIds(nearGrid.parentElement || nearGrid);
        intersects = Array.from(parents).some(id => PARENT_IDS.has(String(id)));
      }
      if (!intersects) return;

      section.querySelectorAll('select[name="solution-category"], .jet-select__control[name="solution-category"]').forEach(sel=>{
        const options = Array.from(sel.options);
        let changed = false;

        options.forEach(opt=>{
          const val = (opt.value || '').trim();
          const txt = normalizeLabel(opt.getAttribute('data-label') || opt.textContent || '');
          // tenta derivar slug a partir do label
          const slug = txt.replace(/\s+/g,'-'); // aproximação segura
          if (HIDE_IDS.has(val) || HIDE_NAMES.has(txt) || HIDE_SLUGS.has(slug)) {
            opt.remove();
            changed = true;
          }
        });

        // Se removeu a opção selecionada ou não tem seleção válida, ajusta
        if (changed){
          if (!sel.options.length){
            const placeholder = document.createElement('option');
            placeholder.value = '';
            placeholder.textContent = (document.documentElement.lang||'').startsWith('pt') ? 'Sem subcategorias'
                                   : (document.documentElement.lang||'').startsWith('en') ? 'No subcategories'
                                   : 'Sin subcategorías';
            placeholder.disabled = true;
            placeholder.selected = true;
            sel.appendChild(placeholder);
          } else {
            // Se sobrou só 1, seleciona ela; senão garante que a seleção é válida
            if (sel.options.length === 1){
              sel.selectedIndex = 0;
            } else if (sel.selectedIndex < 0 || !sel.value){
              sel.selectedIndex = 0;
            }
          }
          // Dispara eventos para Jet Smart Filters
          const ev1 = new Event('change', {bubbles:true});
          const ev2 = new Event('input',  {bubbles:true});
          sel.dispatchEvent(ev1);
          sel.dispatchEvent(ev2);
        }
      });
    });
  }

  // ---------- Orquestração ----------
  function run(){
    filterSubcategoryList();
    filterSolutionSelect();
  }

  // dispara agora + nos momentos relevantes
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', run, {once:true});
  } else {
    run();
  }
  window.addEventListener('load', run);

  // quando trocar país
  document.addEventListener('change', function(e){
    const t = e.target;
    if (t && t.matches && t.matches('select[name="geot_dropdown"]')) {
      setTimeout(run, 0);
    }
  }, true);

  // mutações (Elementor/Jet repovoa listas)
  const root = document.getElementById('geo-menu-modal') || document.body;
  new MutationObserver(()=>setTimeout(run,0))
    .observe(root, {subtree:true, childList:true, attributes:true, attributeFilter:['class','style','data-queried-id']});

  // se você tiver queueClean(), roda depois dele
  try {
    if (typeof queueClean === 'function') {
      const _qc = queueClean;
      window.queueClean = function(){
        _qc();
        setTimeout(run, 0);
      };
    }
  } catch(e){}
})();
